    throw new Error('Missing required field: user_ids');
  }
  if (!isUniqueStringArray(argumentsObj.user_ids)) {
    throw new Error('user_ids must be a non-empty array of unique strings (max 5)');
  }
  return argumentsObj.user_ids;
}

export async function listTools() {
  return [
    {
      name: 'users_get_many',
      description: 'Look up multiple users by id in a single batch. Returns one line per requested id (in request order); missing users are marked but do not fail the batch.',
      inputSchema: {
        type: 'object',
        properties: {
          user_ids: {
            type: 'array',
