            minItems: 1,
            maxItems: 5,
            uniqueItems: true,
            description: 'Unique user ids to look up (1-5 entries).',
          },
        },
        required: ['user_ids'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (!VALID_TOOLS.has(name)) {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const userIds = validateArgs(args || {});
  const lines = userIds.map((id) => {
    const user = users[id];
    if (user && typeof user.name === 'string') {
      return `${id}: ${user.name}`;
    }
    return `${id}: not found`;
  });
  return {
